async function loadDutyRows(token: string) {
  const since = new Date(Date.now() - 45 * 864e5).toLocaleDateString("en-CA");
  const filter = `&duty_date=gte.${since}&order=duty_date.asc&limit=200`;
  try {
    return await request(route("duties", `select=id,duty_date,student_id,target_count,rotation_cycle,duty_status,status_note,student:profiles!duties_student_id_fkey(full_name,enrollment_number)${filter}`), token);
  } catch (e: any) {
    if (!/duty_status|schema cache/i.test(e.message || "")) throw e;
    const rows = await request(route("duties", `select=id,duty_date,student_id,target_count,rotation_cycle,student:profiles!duties_student_id_fkey(full_name,enrollment_number)${filter}`), token);
    return rows.map((d: any) => ({ ...d, duty_status: "assigned", status_note: null }));
  }
}
function csvRows(input:string){
 const rows:string[][]=[];let row:string[]=[],cell="",quoted=false;
 for(let i=0;i<input.length;i++){const c=input[i];if(quoted){if(c==='"'&&input[i+1]==='"'){cell+='"';i++}else if(c==='"')quoted=false;else cell+=c}else if(c==='"')quoted=true;else if(c===","){row.push(cell);cell=""}else if(c==="\n"){row.push(cell);rows.push(row);row=[];cell=""}else if(c!=="\r")cell+=c}
 row.push(cell);if(row.some(x=>x.trim()))rows.push(row);if(rows.length<2)throw Error("CSV needs a header row and at least one question.");
 const headers=rows.shift()!.map(x=>x.trim().toLowerCase().replace(/[ -]+/g,"_"));
 return rows.map(cols=>Object.fromEntries(headers.map((h,i)=>[h,(cols[i]||"").trim()])));
}
function parseImported(raw:string){
 let records:any[];
 try{const parsed=JSON.parse(raw);records=Array.isArray(parsed)?parsed:Array.isArray(parsed.questions)?parsed.questions:[parsed]}catch{records=csvRows(raw)}
 if(!records.length)throw Error("No questions were found in that file.");
 return records.map((r:any,i:number)=>{
  const stem=String(r.stem??r.question??"").trim(),options=Array.isArray(r.options)?r.options:Array.isArray(r.choices)?r.choices:[r.option_a??r.a,r.option_b??r.b,r.option_c??r.c,r.option_d??r.d];
  const clean:string[]=options.map((v:any)=>String(v??"").trim());
  const answer=r.correct_index??r.answer_index??r.correct_answer??r.answer??r.correct_option,answerText=String(answer??"").trim();
  let index=-1;
  if(typeof answer==="number"&&Number.isInteger(answer)&&answer>=0&&answer<=3)index=answer;
  else if(/^[0-4]$/.test(answerText)){index=Number(answerText);if(index>0)index-=1}
  if(index<0)index=clean.findIndex(v=>v.toLowerCase()===answerText.toLowerCase());
  if(index<0&&/^[a-d]$/i.test(answerText))index=answerText.toUpperCase().charCodeAt(0)-65;
  if(stem.length<12)throw Error(`Question ${i+1}: question text must have at least 12 characters.`);
  if(clean.length!==4||clean.some((v:string)=>!v))throw Error(`Question ${i+1}: provide exactly four options.`);
  if(index<0||index>3)throw Error(`Question ${i+1}: correct answer must match an option or be a zero-based/one-based index or A–D.`);
  return {stem,topic:String(r.topic||"Other"),options:clean,correct_index:index,explanation:String(r.explanation||"").trim()||null,source_url:String(r.source_url??r.source??"").trim()||null};
 });
}
function Source({value}:{value:string|null|undefined}){if(!value)return null;const url=/^https?:\/\//i.test(value);return <p className="source"><b>Source:</b> {url?<a href={value} target="_blank" rel="noopener noreferrer">{value} <ExternalLink size={13}/></a>:value}</p>}

